package ru.local.jarvis;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.OpenableColumns;import android.util.Base64;import android.widget.*;import java.io.*;import org.json.*;

/** Explicit system picker/share import. Never scans device storage. */
public final class DocumentImport extends Activity {
 public void onCreate(Bundle state){super.onCreate(state);setTitle("Импорт документа в Jarvis");if(state!=null)return;Intent intent=getIntent();if(Intent.ACTION_SEND.equals(intent.getAction())){Uri uri=intent.getParcelableExtra(Intent.EXTRA_STREAM);confirm(uri);}else{Intent picker=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*");picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"text/plain","text/csv","text/markdown","application/json","application/pdf","image/jpeg","image/png","image/webp","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});try{startActivityForResult(picker,1);}catch(Exception e){error("Не удалось открыть выбор файла");}}}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==1){if(result!=RESULT_OK||data==null){finish();return;}confirm(data.getData());}}
 void confirm(Uri uri){if(uri==null||!"content".equals(uri.getScheme())){error("Выберите документ через системный список файлов");return;}String found="";try(Cursor cursor=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())found=cursor.getString(0);}catch(Exception ignored){}final String name=found;if(name==null||!name.toLowerCase(java.util.Locale.ROOT).matches(".*\\.(txt|md|csv|json|pdf|docx|xlsx|jpg|jpeg|png|webp)$")){error("Поддерживаются TXT, MD, CSV, JSON, PDF, DOCX и XLSX до 4 МБ");return;}new AlertDialog.Builder(this).setTitle("Импортировать в Jarvis?").setMessage(name+"\nДокумент будет передан на ваш сервер для поиска и анализа.").setPositiveButton("Импортировать",(d,w)->upload(uri,name)).setNegativeButton("Отмена",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
 void upload(Uri uri,String name){TextView wait=new TextView(this);wait.setPadding(40,40,40,40);wait.setText("Импортирую документ…");setContentView(wait);new Thread(()->{try{byte[] content=Net.read(getContentResolver().openInputStream(uri),4*1024*1024);JSONObject response=Net.call(this,"/library/import",new JSONObject().put("name",name).put("content",Base64.encodeToString(content,Base64.NO_WRAP)));String message="Документ добавлен: "+response.optString("name",name);Assistant.last=message;runOnUiThread(()->{if(!isFinishing())new AlertDialog.Builder(this).setMessage(message).setPositiveButton("Готово",(d,w)->finish()).show();});}catch(Exception e){runOnUiThread(()->error("Не удалось импортировать документ. Проверьте формат, размер до 4 МБ и соединение с сервером."));}},"JarvisDocumentImport").start();}
 void error(String message){if(isFinishing())return;new AlertDialog.Builder(this).setTitle("Jarvis").setMessage(message).setPositiveButton("Закрыть",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
}
